 aea1:{tag:"RA1 · 12 HORES",title:"Laboratori de pensament",meta:["4 sessions","10% del mòdul"],intro:"Quatre sessions progressives per passar de l’anàlisi guiada a la creació d’un repte propi.",steps:["S1 · Desmuntem el problema.","S2 · Programem persones.","S3 · Detectius de l’error.","S4 · Escape algorítmic i defensa."],success:"Avaluació prevista: Ex1 individual (40%) + projecte Pj1.1 (60%)."}
