const dialog=document.querySelector('#detailDialog'),content=document.querySelector('#dialogContent');
document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>{const d=details[b.dataset.open];content.innerHTML=`<div class="dialog-body"><span class="tag">${d.tag}</span><h2>${d.title}</h2><p>${d.intro}</p><div class="meta">${d.meta.map(x=>`<span>${x}</span>`).join('')}</div><ol>${d.steps.map(x=>`<li>${x}</li>`).join('')}</ol><div class="success">${d.success}</div><div class="dialog-actions"><button class="primary" onclick="document.querySelector('#detailDialog').close()">Entès, continuem</button></div></div>`;dialog.showModal()}));
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
const mode=document.querySelector('#modeBtn'),panel=document.querySelector('#teacherPanel');mode.addEventListener('click',()=>{const on=document.body.classList.toggle('teacher');mode.setAttribute('aria-pressed',on);mode.innerHTML=on?'<span>●</span> Vista professorat':'<span>●</span> Vista alumnat';panel.hidden=!on;if(on)panel.scrollIntoView({behavior:'smooth',block:'center'})});
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');const f=btn.dataset.filter;document.querySelectorAll('.resource-list a').forEach(a=>{a.style.display=f==='all'||a.dataset.kind===f?'grid':'none'});if(f==='teacher'&&!document.body.classList.contains('teacher')){document.body.classList.add('teacher');panel.hidden=false;mode.innerHTML='<span>●</span> Vista professorat';mode.setAttribute('aria-pressed','true')}}));
const menu=document.querySelector('#menuBtn'),bar=document.querySelector('.topbar');menu.addEventListener('click',()=>{const on=bar.classList.toggle('open');menu.setAttribute('aria-expanded',on)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>bar.classList.remove('open')));
